import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.vLhlLNVn.js";const n="/assets/okta-create-app.DKE-eakl.png",o="/assets/okta-choose-saml.BPQ1Rcqo.png",l="/assets/okta-general.erXD8zJX.png",r="/assets/okta-general-2.DlTRog-6.png",p="/assets/okta-advanced-settings.Z183l0dv.png",d="/assets/okta-attribute-settings.CzoLMKjm.png",h="/assets/okta-assign-users.pYnoFwZA.png",c="/assets/craft-mapping-attributes.afogbInF.png",S=JSON.parse('{"title":"Okta","description":"","frontmatter":{},"headers":[],"relativePath":"idps/okta.md","filePath":"idps/okta.md"}'),u={name:"idps/okta.md"};function g(m,e,k,f,b,v){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="okta" tabindex="-1">Okta <a class="header-anchor" href="#okta" aria-label="Permalink to &quot;Okta&quot;">​</a></h1><h2 id="create-the-craft-sp-provider-my-provider" tabindex="-1">Create the Craft SP Provider (My Provider) <a class="header-anchor" href="#create-the-craft-sp-provider-my-provider" aria-label="Permalink to &quot;Create the Craft SP Provider (My Provider)&quot;">​</a></h2><p>Within Craft CMS, after the plugin is installed, on the control panel left side navigation click SAML Service Provider &gt; &quot;My Provider&quot;. Click &quot;Generate key pair&quot; (under the Security tab), label the provider, and hit save.</p><p>Then go back to the provider you just created and click on the Metadata tab. Leave this browser tab open for easy access while configuring Okta.</p><h2 id="create-the-application" tabindex="-1">Create the Application <a class="header-anchor" href="#create-the-application" aria-label="Permalink to &quot;Create the Application&quot;">​</a></h2><p><img src="'+n+'" alt="Create the Application"></p><h3 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h3><p>Name the application accordingly and choose SAML 2.0 application.</p><p><img src="'+o+'" alt="Choose SAML 2.0"></p><p><img src="'+l+'" alt="Name the Application"></p><h4 id="configure-saml" tabindex="-1">Configure SAML <a class="header-anchor" href="#configure-saml" aria-label="Permalink to &quot;Configure SAML&quot;">​</a></h4><ul><li>Single sign on URL: Set this to your Craft SP (My Provider) Assertion Consumer Service (ACS) found on the Metadata tab. <ul><li>For example, <code>https://your-craft-domain.com/sso/login/1f85b98a-125a-4f34-8daf-4325077c065e</code></li></ul></li><li>Audience URI (SP Entity ID): Set this to the SP entity ID</li><li>Default RelayState: You can leave this blank</li><li>Name ID format: can be left as blank</li><li>Application username: Setting this to the Okta username is a good idea because if the user ever changes their email, their user in Craft will stay the same.</li><li>Update application username on: You can leave this as &quot;Create and update&quot;</li></ul><p><img src="'+r+'" alt="Name the Application"></p><h4 id="advanced-setting" tabindex="-1">Advanced Setting <a class="header-anchor" href="#advanced-setting" aria-label="Permalink to &quot;Advanced Setting&quot;">​</a></h4><ul><li>Response: Signed</li><li>Assertion Signature: Signed</li><li>Signature Algorithm: leave on default</li><li>Digest Algorithm: leave on default</li><li>Assertion Encryption: For elevated security you can choose to encrypt but for this example, we&#39;ll leave as unencrypted due to us signing the Response and Assertion.</li><li>Enable Single Logout: Checked <ul><li>Single Logout URL: Set this to your Craft SP (My Provider) Single Logout Service URL found on the Metadata tab. <ul><li>For example, <code>https://your-craft-domain.com/sso/logout/1f85b98a-125a-4f34-8daf-4325077c065e</code></li></ul></li><li>SP Issuer: set as the Entity ID (same as the Entity ID set above)</li><li>Signature Certificate: Download from the Craft SP (My Provider) Security Tab, in Craft, and hit upload.</li></ul></li><li>Assertion Inline Hook: leave as is</li><li>Honor Force Authentication: leave as is</li><li>SAML Issuer ID: leave as is</li></ul><p><img src="'+p+'" alt="Advanced Settings"></p><h4 id="attribute-statement" tabindex="-1">Attribute Statement <a class="header-anchor" href="#attribute-statement" aria-label="Permalink to &quot;Attribute Statement&quot;">​</a></h4><p>These are the attributes sent over in the assertion. All of the attributes sent over from here can be mapped to the Craft user. At the minimum, email is required. But for this example, we&#39;ll do first and last name as well.</p><ul><li>Under the first attribute statement: <ul><li>Name: <code>FirstName</code> ( 👈 this is what the Craft plugin will see as the attribute name)</li><li>Name format: leave as is (unspecified)</li><li>Value: <code>user.firstName</code></li></ul></li><li>Under the second attribute statement: <ul><li>Name: <code>LastName</code></li><li>Name format: leave as is (unspecified)</li><li>Value: <code>user.lastName</code></li></ul></li><li>Under the third attribute statement: <ul><li>Name: <code>Email</code></li><li>Name format: leave as is (unspecified)</li><li>Value: <code>user.email</code></li></ul></li></ul><p><img src="'+d+'" alt="Attribute Statement"></p><h4 id="group-attribute-statements-optional" tabindex="-1">Group Attribute Statements (optional) <a class="header-anchor" href="#group-attribute-statements-optional" aria-label="Permalink to &quot;Group Attribute Statements (optional)&quot;">​</a></h4><p>Here&#39;s where you can send over group data and sync it to Craft. For now, we&#39;ll skip this step.</p><h4 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h4><p>Just click Finish</p><h3 id="assign-users" tabindex="-1">Assign Users <a class="header-anchor" href="#assign-users" aria-label="Permalink to &quot;Assign Users&quot;">​</a></h3><p>In Okta, on the application page for your newly created application, click the assignments tab, then the &quot;Assign&quot; and assign users or groups as needed.</p><p><img src="'+h+'" alt="Assign users"></p><h2 id="copy-over-the-metadata-from-okta" tabindex="-1">Copy Over the Metadata (From Okta) <a class="header-anchor" href="#copy-over-the-metadata-from-okta" aria-label="Permalink to &quot;Copy Over the Metadata (From Okta)&quot;">​</a></h2><p>After you click the &quot;Finish&quot; button on the Feedback page, there&#39;s a button on the right side column labeled &quot;View SAML setup instructions&quot;. At the bottom of the page copy the XML in the &quot;Optional&quot; (Provide the following IDP metadata to your SP provider) field.</p><p>Then run through the following step:</p><ul><li>Within Craft CMS, goto the SAML Service Provider plugin and click &quot;Provider List&quot; &gt; &quot;+ Add Identity Provider&quot;</li><li>On the provider page, Label the provider as needed (i.e., Okta Production) and paste the XML Metadata from Okta into the <code>2. Metadata XML</code> on the Metadata field</li><li>Then, click on the Configure tab and setup the Mapping at the bottom as below (this will mirror what we configured in Okta): <ul><li>Click on the &quot;+ Add a new mapping&quot; for first name: <ul><li>Attribute Name: <code>FirstName</code></li><li>Select &quot;First Name&quot; from the dropdown</li></ul></li><li>Continue to last name: <ul><li>Attribute Name: <code>LastName</code></li><li>Select &quot;Last Name&quot;</li></ul></li><li>Add email <ul><li>Attribute Name: <code>Email</code></li><li>Select &quot;Email&quot;</li></ul></li></ul></li><li>Click Save</li></ul><p><img src="'+c+`" alt="Mapping Attributes"></p><h2 id="finish-and-test" tabindex="-1">Finish and Test <a class="header-anchor" href="#finish-and-test" aria-label="Permalink to &quot;Finish and Test&quot;">​</a></h2><p>Copy the UID from the new Okta and add/replace the <code>loginPath</code> value in Craft&#39;s <code>config/general.php</code> file, with this format <code>/sso/login/request/&lt;okta-uid&gt;</code>.</p><p>For example:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;loginPath&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/sso/login/request/f2885601-e655-49ac-a2c5-48e702db6bfa&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>To test, create a protected test page using like the following:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% requireLogin %}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ currentUser.fullName }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ currentUser.email }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ currentUser.username }}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ currentUser.dateCreate }}</span></span></code></pre></div><p>Use an incognito tab or signed out from Craft, goto your newly created page and you be should redirected to the Okta (the IdP). Login and see that you will be returned back to the newly created page.</p>`,39)])])}const A=t(u,[["render",g]]);export{S as __pageData,A as default};
